## Code Example

```javascript
// Memoized selector sketch (conceptual)
import { createSelector } from '@reduxjs/toolkit';

const selectEvents = (state) => state.metrics.events; // raw events stream

const bucketizeBySecond = createSelector(
  [selectEvents],
  (events) => {
    const buckets = [];
    let current = [];
    let currentSecond = null;
    for (const e of events) {
      const t = Math.floor(e.ts / 1000) * 1000;
      if (currentSecond !== t) {
        if (current.length) buckets.push(current);
        current = [e];
        currentSecond = t;
      } else {
        current.push(e);
      }
    }
    if (current.length) buckets.push(current);
    return buckets;
  }
);
```

